<?php declare(strict_types=1);
require_once __DIR__.'/../../src/Documents/InterfaceText.php';
$shareText=\Kulturhus\Verein\Documents\InterfaceText::text(...);$shareFormat=\Kulturhus\Verein\Documents\InterfaceText::format(...);
$sharing=\Kulturhus\Verein\Web\DocumentSharingForm::state($db,(string)$_SESSION['actor'],$docId,$_POST,$doc);$shareDoc=$sharing['doc'];$savedShares=$sharing['grants'];$people=$sharing['choices'];$sharePeople=[];
if($sharing['selected'])$sharePeople[$sharing['selected']['id']]=$sharing['selected'];foreach($people['rows']as$person)$sharePeople[$person['id']]=$person;
?>
<section class="card" data-document-interface data-document-sharing><h2><?= e($shareText('Persönliche Freigabe im Mitgliederportal')) ?></h2>
<p><?= e($shareText('Nur die ausgewählte Person erhält Zugriff auf die freigegebene Dateiversion. Neue Versionen müssen erneut freigegeben werden. Prüfe vor der Freigabe, ob die Datei Angaben anderer Personen enthält.')) ?></p>
<p><?= e($shareFormat('Geprüfte Dateifassung: {revision}',['revision'=>$sharing['revision']])) ?></p>
<?php foreach($sharing['errors']as$shareError): ?><p role="alert"><?= e($shareText($shareError)) ?></p><?php endforeach ?>
<?php if($sharing['stale']): ?><p role="alert"><?= e($shareText('Das Dokument oder die persönlichen Freigaben wurden inzwischen geändert. Aktuelle Fassung neu öffnen und vor dem Speichern prüfen.')) ?></p><?php endif ?>
<?php if($shareDoc['state']!=='active'): ?><p><?= e($shareText('Archivierte Dokumente zuerst wieder aktivieren. Bestehende Freigaben können zurückgenommen werden.')) ?></p><?php endif ?>
<p><a class="btn btn-outline theme-secondary" data-share-review data-navigation-native href="<?= e(url(['view'=>'documents','doc'=>$docId]+scalarFields($_GET,['scope','q','folder','kind','state','unassigned','source_type','source_id','recursive','page','size','doc_mode']))) ?>"><?= e($shareText('Aktuelle Fassung neu öffnen und prüfen')) ?></a></p>
<form method="post" action="<?= e(url(['view'=>'documents','doc'=>$docId]+scalarFields($_GET,['scope','q','folder','kind','state','unassigned','source_type','source_id','recursive','page','size','doc_mode']))) ?>" data-document-sharing-form><?= csrf().hidden('action','portal-share').hidden('doc',$docId).hidden('version',$sharing['version']).hidden('revision',$sharing['revision']) ?>
<fieldset data-document-share-grants><legend><?= e($shareText('Gespeicherte Freigaben')) ?></legend>
<div class="doc-source-controls"><label><?= e($shareText('Gespeicherte Freigaben suchen')) ?><input class="form-control" type="search" name="share_query" maxlength="150" value="<?= e($sharing['share_query']) ?>"></label><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="shares-search" formnovalidate><?= e($shareText('Freigaben suchen')) ?></button></div>
<?php if(!$sharing['all_grants']): ?><p><?= e($shareText('Dieses Dokument ist noch für keine Person persönlich freigegeben.')) ?></p><?php elseif(!$savedShares['rows']): ?><p><?= e($shareText('Keine gespeicherte Freigabe passt zu dieser Suche.')) ?></p><?php else: ?>
<ul><?php foreach($savedShares['rows']as$savedShare): ?><li><strong><?= e($savedShare['name']) ?></strong>
<?php if($savedShare['archived_at']): ?> · <?= e($shareText('Profil archiviert, derzeit kein Zugriff')) ?><?php elseif($shareDoc['state']!=='active'): ?> · <?= e($shareText('Dokument archiviert, derzeit kein Zugriff')) ?><?php elseif((int)$savedShare['revision']!==(int)$shareDoc['revision']): ?> · <?= e($shareText('Ältere Version bleibt freigegeben. Die aktuelle Datei ist für diese Person noch nicht freigegeben.')) ?><?php else: ?> · <?= e($shareText('Aktuelle Version freigegeben')) ?><?php endif ?>
 · <?= e($shareFormat('gespeichert am {date}',['date'=>dateDe(substr(localDateTime($savedShare['created_at']),0,10))])) ?> <button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="select:<?= e($savedShare['contact_id']) ?>" formnovalidate><?= e($shareText('Diese Person auswählen')) ?></button></li><?php endforeach ?></ul><?php endif ?>
<p role="status"><?= e($shareFormat('Freigabeseite {page} von {pages} · {count} Freigaben',['page'=>$savedShares['page'],'pages'=>$savedShares['pages'],'count'=>$savedShares['total']])) ?></p>
<div class="doc-source-controls"><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="shares-previous" formnovalidate <?= $savedShares['page']<=1?'disabled':'' ?>><?= e($shareText('Vorherige')) ?></button><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="shares-next" formnovalidate <?= $savedShares['page']>=$savedShares['pages']?'disabled':'' ?>><?= e($shareText('Nächste')) ?></button><label><?= e($shareText('Freigabeseite')) ?><input class="form-control" name="share_page" inputmode="numeric" pattern="[1-9][0-9]{0,8}" value="<?= e($sharing['errors']?$sharing['share_page']:(string)$savedShares['page']) ?>"></label><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="shares-page" formnovalidate><?= e($shareText('Seite öffnen')) ?></button></div>
</fieldset>
<fieldset data-document-share-people><legend><?= e($shareText('Person für die Freigabe auswählen')) ?></legend><p><?= e($shareText('Sechs Kontakte pro Seite. Die ausgewählte Person bleibt beim Suchen und Blättern erhalten. Die Suche speichert keine Freigabe.')) ?></p>
<div class="doc-source-controls"><label><?= e($shareText('Person suchen')) ?><input class="form-control" type="search" name="contact_query" maxlength="150" value="<?= e($sharing['query']) ?>"></label><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="contact-search" formnovalidate><?= e($shareText('Personen suchen')) ?></button></div>
<label><?= e($shareText('Person')) ?><select class="form-control" name="contact" required><option value=""><?= e($shareText('Bitte Person auswählen')) ?></option><?php foreach($sharePeople as$person): ?><option value="<?= e($person['id']) ?>" <?= $sharing['contact']===$person['id']?'selected':'' ?>><?= e($person['name']) ?><?= !empty($person['archived_at'])?' · '.e($shareText('Profil archiviert · nur zurücknehmen')):(!empty($person['unavailable'])?' · '.e($shareText('Person derzeit nicht verfügbar')):'') ?></option><?php endforeach ?></select></label>
<p role="status"><?= e($shareFormat('Personenseite {page} von {pages} · {count} Kontakte',['page'=>$people['page'],'pages'=>$people['pages'],'count'=>$people['total']])) ?></p>
<div class="doc-source-controls"><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="contact-previous" formnovalidate <?= $people['page']<=1?'disabled':'' ?>><?= e($shareText('Vorherige')) ?></button><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="contact-next" formnovalidate <?= $people['page']>=$people['pages']?'disabled':'' ?>><?= e($shareText('Nächste')) ?></button><label><?= e($shareText('Personenseite')) ?><input class="form-control" name="contact_page" inputmode="numeric" pattern="[1-9][0-9]{0,8}" value="<?= e($sharing['errors']?$sharing['page']:(string)$people['page']) ?>"></label><button type="submit" class="btn btn-outline theme-secondary" name="share_read" value="contact-page" formnovalidate><?= e($shareText('Seite öffnen')) ?></button></div>
</fieldset>
<label><?= e($shareText('Aktion')) ?><select class="form-control" name="enabled" required><?php if(!in_array($sharing['enabled'],['0','1'],true)): ?><option value="<?= e($sharing['enabled']) ?>" selected><?= e($shareText('Freigabeaktion auswählen.')) ?></option><?php endif ?><option value="1" <?= $sharing['enabled']==='1'?'selected':'' ?>><?= e($shareText('Aktuelle Version freigeben')) ?></option><option value="0" <?= $sharing['enabled']==='0'?'selected':'' ?>><?= e($shareText('Freigabe für diese Person zurücknehmen')) ?></option></select></label><button class="btn btn-solid theme-primary" <?= !$sharing['reviewed']||$sharing['stale']?'disabled':'' ?>><?= e($shareText('Freigabe speichern')) ?></button></form></section>
